fn strip_parens(s: str) -> str:
    n = len(s)
    var out = ""
    var i = 0
    while i < n:
        var j = i
        if s[j] == " ":
            j += 1
        if j < n and s[j] == "(":
            var k = j + 1
            while k < n and s[k] != ")":
                k += 1
            if k < n and k > j + 1:
                i = k + 1
                continue
        out += s[i]
        i += 1
    return out

